import java.util.*;

public class Solution {
  public static int[] solve(int[] input) {
    int[] sorted = input.clone();
    Arrays.sort(sorted);
    Map<Integer, Integer> rank = new HashMap<>();
    for (int x : sorted) if (!rank.containsKey(x)) rank.put(x, rank.size() + 1);
    int[] out = new int[input.length];
    for (int i = 0; i < out.length; i++) out[i] = rank.get(input[i]);
    return out;
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {40, 10, 20, 30, 20})));
  }
}

Task Scheduler.source:
import java.util.*;

public class Solution {
  public static long solve(char[] tasks, int cooldown) {
    if (cooldown < 0) throw new IllegalArgumentException();
    int[] count = new int[26];
    for (char c : tasks) {
      if (c < 'A' || c > 'Z') throw new IllegalArgumentException();
      count[c - 'A']++;
    }
    int max = 0, ties = 0;
    for (int f : count) max = Math.max(max, f);
    for (int f : count) if (f == max && f > 0) ties++;
    return Math.max(tasks.length, (long) (max - 1) * (cooldown + 1L) + ties);
  }

  public static void main(String[] args) {
    System.out.println(solve(new char[] {'A', 'A', 'A', 'B', 'B', 'B'}, 2));
  }
}

Hand of Straights.source:
import java.util.*;

public class Solution {
  public static boolean solve(int[] hand, int group) {
    if (group <= 0) throw new IllegalArgumentException();
    if (hand.length % group != 0) return false;
    TreeMap<Integer, Integer> count = new TreeMap<>();
    for (int x : hand) count.put(x, count.getOrDefault(x, 0) + 1);
    while (!count.isEmpty()) {
      int start = count.firstKey();
      for (int i = 0; i < group; i++) {
        long value = (long) start + i;
        if (value > Integer.MAX_VALUE) return false;
        int x = (int) value;
        Integer f = count.get(x);
        if (f == null) return false;
        if (f == 1) count.remove(x);
        else count.put(x, f - 1);
      }
    }
    return true;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 2, 3, 6, 2, 3, 4, 7, 8}, 3));
  }
}

Design Twitter.source:
import java.util.*;

public class Solution {
  static class Twitter {
    static class Tweet {
      int id;
      long time;

      Tweet(int id, long time) {
        this.id = id;
        this.time = time;
      }
    }

    long clock;
    final Map<Integer, List<Tweet>> posts = new HashMap<>();
    final Map<Integer, Set<Integer>> following = new HashMap<>();

    void postTweet(int user, int id) {
      posts.computeIfAbsent(user, k -> new ArrayList<>()).add(new Tweet(id, clock++));
    }

    void follow(int user, int other) {
      following.computeIfAbsent(user, k -> new HashSet<>()).add(other);
    }

    void unfollow(int user, int other) {
      Set<Integer> set = following.get(user);
      if (set != null) set.remove(other);
    }

    List<Integer> getNewsFeed(int user) {
      Set<Integer> users = new HashSet<>(following.getOrDefault(user, Collections.emptySet()));
      users.add(user);
      PriorityQueue<Tweet> q = new PriorityQueue<>((a, b) -> Long.compare(a.time, b.time));
      for (int u : users)
        for (Tweet t : posts.getOrDefault(u, Collections.emptyList())) {
          q.offer(t);
          if (q.size() > 10) q.poll();
        }
      List<Integer> out = new ArrayList<>();
      while (!q.isEmpty()) out.add(q.poll().id);
      Collections.reverse(out);
      return out;
    }
  }

  public static void main(String[] args) {
    Twitter t = new Twitter();
    t.postTweet(1, 5);
    t.follow(1, 2);
    t.postTweet(2, 6);
    System.out.println(t.getNewsFeed(1));
    t.unfollow(1, 2);
    System.out.println(t.getNewsFeed(1));
  }
}

Minimum Cost to Connect Sticks.source:
import java.util.*;

public class Solution {
  public static long solve(int[] a) {
    PriorityQueue<Long> q = new PriorityQueue<>();
    for (int x : a) {
      if (x < 0) throw new IllegalArgumentException();
      q.offer((long) x);
    }
    long cost = 0;
    while (q.size() > 1) {
      long joined = q.poll() + q.poll();
      cost += joined;
      q.offer(joined);
    }
    return cost;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {2, 4, 3}));
  }
}

Maximum Sum Combination.source:
import java.util.*;

public class Solution {
  static class Pair {
    int i, j;
    long sum;

    Pair(int i, int j, int[] a, int[] b) {
      this.i = i;
      this.j = j;
      sum = (long) a[i] + b[j];
    }
  }

  public static List<Long> solve(int[] aa, int[] bb, int k) {
    if (k < 0 || (long) k > (long) aa.length * bb.length) throw new IllegalArgumentException();
    int[] a = aa.clone(), b = bb.clone();
    Arrays.sort(a);
    Arrays.sort(b);
    List<Long> out = new ArrayList<>();
    if (k == 0) return out;
    PriorityQueue<Pair> q = new PriorityQueue<>((x, y) -> Long.compare(y.sum, x.sum));
    Set<Long> seen = new HashSet<>();
    int i = a.length - 1, j = b.length - 1;
    q.offer(new Pair(i, j, a, b));
    seen.add(((long) i << 32) | (j & 0xffffffffL));
    while (out.size() < k) {
      Pair p = q.poll();
      out.add(p.sum);
      for (int[] index : new int[][] {{p.i - 1, p.j}, {p.i, p.j - 1}})
        if (index[0] >= 0 && index[1] >= 0) {
          long key = ((long) index[0] << 32) | (index[1] & 0xffffffffL);
          if (seen.add(key)) q.offer(new Pair(index[0], index[1], a, b));
        }
    }
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 4, 2, 3}, new int[] {2, 5, 1, 6}, 3));
  }
}

Find Median from Data Stream.source:
import java.util.*;

public class Solution {
  static class MedianFinder {
    final PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder()),
        high = new PriorityQueue<>();

    void add(int x) {
      if (low.isEmpty() || x <= low.peek()) low.offer(x);
      else high.offer(x);
      if (low.size() > high.size() + 1) high.offer(low.poll());
      if (high.size() > low.size()) low.offer(high.poll());
    }

    double median() {
      if (low.isEmpty()) throw new NoSuchElementException();
      return low.size() > high.size() ? low.peek() : ((long) low.peek() + high.peek()) / 2.0;
    }
  }

  public static void main(String[] args) {
    MedianFinder m = new MedianFinder();
    m.add(1);
    m.add(2);
    System.out.println(m.median());
    m.add(3);
    System.out.println(m.median());
  }
}

Top K Frequent Elements.source:
import java.util.*;

public class Solution {
  public static List<Integer> solve(int[] a, int k) {
    Map<Integer, Integer> f = new HashMap<>();
    for (int x : a) f.put(x, f.getOrDefault(x, 0) + 1);
    if (k < 0 || k > f.size()) throw new IllegalArgumentException();
    List<Integer> keys = new ArrayList<>(f.keySet());
    keys.sort(
        (x, y) -> {
          int c = Integer.compare(f.get(y), f.get(x));
          return c != 0 ? c : Integer.compare(x, y);
        });
    return new ArrayList<>(keys.subList(0, k));
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 1, 1, 2, 2, 3}, 2));
  }
}
